 async function save(color){if(writing||!ready)return;const target=editing&&marks.find(m=>m.id===editing);if(!target&&!pending?.length)return;const token=epoch,id=target?.id||crypto.randomUUID(),now=Date.now(),record=target?{...target,color,updatedAt:now}:{id,book,color,anchors:pending,createdAt:now,updatedAt:now,schema:1};writing=true;try{await HighlightStore.put(record);if(token!==epoch)return;marks=marks.filter(m=>m.id!==id).concat(record);closePalette();root.ReaderSelection.invalidate('');sheetRects=currentRects();root.ReaderSelection.protect();draw();E('highlightStatus').textContent='브라우저에 저장했습니다. 자동 백업·동기화는 아직 지원하지 않습니다.';toast(target?'하이라이트 색상을 변경했습니다.':'하이라이트를 저장했습니다.')}catch(e){toast('저장 실패: '+e.message)}finally{writing=false;draw()}}
